<script setup>
import { onBeforeUnmount, onMounted, reactive, ref } from 'vue';
const props=defineProps({mode:String,indexUrl:String,createUrl:String,storeUrl:String,updateUrl:String,csrf:String,payload:String,errors:String,old:String});
const json=(s,d={})=>{try{return s?JSON.parse(s):d}catch{return d}};const supplied=json(props.payload);const refund=supplied.refund||{};const issues=json(props.errors);const old=json(props.old);const form=reactive({order_id:old.order_id??refund.order_id??'',amount:old.amount??refund.amount??'',reason:old.reason??refund.reason??'',note:old.note??refund.note??''});
const state=reactive({rows:[],stats:{},pagination:{},filters:{search:'',status:'',sort:'newest'}});const loading=ref(true),error=ref('');let timer,abort;
async function load(url=location.href,push=false){abort?.abort();abort=new AbortController();loading.value=true;error.value='';try{const r=await fetch(url,{credentials:'same-origin',signal:abort.signal,headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'}});const d=await r.json();if(!r.ok)throw new Error(d.message||`Request failed (${r.status})`);state.rows=d.refunds||[];state.stats=d.stats||{};state.pagination=d.pagination||{};if(push)history.pushState({},'',url)}catch(e){if(e.name!=='AbortError')error.value=e.message}finally{loading.value=false}}
function filtered(){const u=new URL(props.indexUrl,location.origin);for(const[k,v]of Object.entries(state.filters))if(v&&!(k==='sort'&&v==='newest'))u.searchParams.set(k,v);return u.href}function apply(){load(filtered(),true)}function search(){clearTimeout(timer);timer=setTimeout(apply,350)}function page(link){if(link.url)load(link.url,true)}
async function action(url,status=null,method='POST'){let ok=true;if(window.Swal){const result=await window.Swal.fire({title:status?`${status[0].toUpperCase()+status.slice(1)} refund?`:'Delete refund?',text:'Please confirm this refund action.',icon:'warning',showCancelButton:true,confirmButtonText:'Continue'});ok=result.isConfirmed}else ok=confirm('Confirm refund action?');if(!ok)return;const body=new URLSearchParams();if(status)body.set('status',status);try{const r=await fetch(url,{method,credentials:'same-origin',headers:{Accept:'application/json','Content-Type':'application/x-www-form-urlencoded','X-CSRF-TOKEN':props.csrf,'X-Requested-With':'XMLHttpRequest'},body:body.toString()});const d=await r.json();if(!r.ok)throw new Error(d.message||'Refund action failed');if(window.Swal)window.Swal.fire({toast:true,position:'top-end',icon:'success',title:d.message,showConfirmButton:false,timer:2200});if(props.mode==='index')await load(location.href);else location.reload()}catch(e){error.value=e.message}}
function pop(){load(location.href)}onMounted(()=>{if(props.mode==='index'){const p=new URLSearchParams(location.search);state.filters={search:p.get('search')||'',status:p.get('status')||'',sort:p.get('sort')||'newest'};load(props.indexUrl+location.search)}window.addEventListener('popstate',pop)});onBeforeUnmount(()=>{clearTimeout(timer);abort?.abort();window.removeEventListener('popstate',pop)});
</script>
<template>
<template v-if="mode==='index'"><section class="refund-hero"><div class="refund-hero-content"><span class="refund-hero-badge"><i class="bi bi-arrow-counterclockwise"></i> Payments Recovery</span><h1>Every refund, under control.</h1><p>Manage customer refund requests, review decisions and track returned payments from one organised workspace.</p></div><div class="refund-hero-mark"><i class="bi bi-receipt-cutoff"></i></div></section>
<section class="refund-stats"><div class="refund-stat stat-blue"><div class="refund-stat-content"><span>Total Refunds</span><strong>{{ Number(state.stats.total||0).toLocaleString() }}</strong></div><div class="refund-stat-icon"><i class="bi bi-receipt"></i></div></div><div class="refund-stat stat-orange"><div class="refund-stat-content"><span>Pending</span><strong>{{ Number(state.stats.pending||0).toLocaleString() }}</strong></div><div class="refund-stat-icon"><i class="bi bi-hourglass-split"></i></div></div><div class="refund-stat stat-green"><div class="refund-stat-content"><span>Processed</span><strong>{{ Number(state.stats.processed||0).toLocaleString() }}</strong></div><div class="refund-stat-icon"><i class="bi bi-check-circle"></i></div></div><div class="refund-stat stat-purple"><div class="refund-stat-content"><span>Refunded Amount</span><strong>${{ Number(state.stats.amount||0).toFixed(2) }}</strong></div><div class="refund-stat-icon"><i class="bi bi-cash-stack"></i></div></div></section>
<section class="refund-panel"><div class="refund-panel-header"><div class="refund-panel-heading"><span class="eyebrow">Refund Directory</span><h5>All Refunds</h5><p>Search, filter and review every customer refund request.</p></div><div class="refund-hero-actions"><a :href="createUrl" class="refund-add-btn"><i class="bi bi-plus-lg"></i><span>Add Refund</span></a></div></div>
<form class="refund-filters" @submit.prevent="apply"><div class="refund-search"><i class="bi bi-search"></i><input v-model="state.filters.search" type="search" placeholder="Refund number, order, customer..." autocomplete="off" aria-label="Search refunds" @input="search"></div><select v-model="state.filters.status" class="refund-select" aria-label="Refund status"><option value="">All Status</option><option v-for="s in ['pending','approved','rejected','processed','cancelled']" :key="s" :value="s">{{ s[0].toUpperCase()+s.slice(1) }}</option></select><select v-model="state.filters.sort" class="refund-select" aria-label="Sort refunds"><option value="newest">Newest</option><option value="oldest">Oldest</option><option value="highest">Highest Amount</option><option value="lowest">Lowest Amount</option></select><div class="refund-filter-actions"><button type="submit" class="refund-filter-btn"><i class="bi bi-funnel"></i><span>Filter</span></button><button v-if="state.filters.search||state.filters.status||state.filters.sort!=='newest'" type="button" class="refund-reset-btn" @click="state.filters={search:'',status:'',sort:'newest'};apply()"><i class="bi bi-x-lg"></i><span>Clear</span></button></div></form>
<div v-if="error" class="refund-alert refund-alert-danger" role="alert">{{ error }} <button class="btn btn-sm btn-light" @click="load()">Retry</button></div><div class="refund-table-wrap" id="refund-table-wrap"><table class="refund-table"><thead><tr><th class="refund-col-number">Refund</th><th class="refund-col-order">Order</th><th class="refund-col-customer">Customer</th><th class="refund-col-amount">Amount</th><th class="refund-col-reason">Reason</th><th class="refund-col-status">Status</th><th class="refund-col-date">Date</th><th class="refund-col-actions">Actions</th></tr></thead><tbody>
<tr v-if="loading"><td colspan="8" class="text-center py-4">Loading refunds…</td></tr><tr v-for="r in state.rows" v-else :key="r.id" :data-refund-row="r.id"><td><div class="refund-number-cell"><div class="refund-number-icon"><i class="bi bi-receipt"></i></div><div><strong>{{ r.refund_number }}</strong><small>Refund Request</small></div></div></td><td><span class="refund-order-number">#{{ r.order_number||'-' }}</span></td><td><div class="refund-customer-cell"><div class="refund-customer-avatar">{{ (r.customer||'C').slice(0,1).toUpperCase() }}</div><div class="refund-customer-info"><strong>{{ r.customer }}</strong><small>{{ r.email||'—' }}</small></div></div></td><td><strong class="refund-amount">${{ r.amount }}</strong></td><td><span class="refund-reason" :title="r.reason">{{ r.reason }}</span></td><td><span class="refund-status" :class="`status-${r.status}`"><i class="bi bi-circle-fill"></i>{{ r.status[0].toUpperCase()+r.status.slice(1) }}</span></td><td><div class="refund-date-block"><span class="refund-date">{{ r.requested_date||'—' }}</span><small>{{ r.requested_time }}</small></div></td><td class="refund-row"><div class="refund-actions"><a :href="r.show_url" class="refund-action action-view" title="View refund"><i class="bi bi-eye"></i></a><a v-if="r.edit_url" :href="r.edit_url" class="refund-action action-edit" title="Edit refund"><i class="bi bi-pencil"></i></a><button v-if="r.status==='pending'" class="refund-action action-approve" title="Approve refund" @click="action(r.status_url,'approved')"><i class="bi bi-check-lg"></i></button><button v-if="r.status==='pending'" class="refund-action action-reject" title="Reject refund" @click="action(r.status_url,'rejected')"><i class="bi bi-x-lg"></i></button><button v-if="r.status==='approved'" class="refund-action action-approve" title="Process refund" @click="action(r.status_url,'processed')"><i class="bi bi-arrow-repeat"></i></button><button v-if="r.status!=='processed'" class="refund-action action-delete" title="Delete refund" @click="action(r.delete_url,null,'DELETE')"><i class="bi bi-trash"></i></button></div></td></tr><tr v-if="!loading&&!state.rows.length"><td colspan="8"><div class="refund-empty"><div class="refund-empty-icon"><i class="bi bi-receipt"></i></div><strong>No refunds found</strong><span>Try changing your filters or search criteria.</span></div></td></tr></tbody></table></div>
<div v-if="state.pagination.total>10" class="refund-pagination"><div class="refund-pagination-info">Showing <strong>{{ state.pagination.first_item }}</strong> to <strong>{{ state.pagination.last_item }}</strong> of <strong>{{ state.pagination.total }}</strong> refunds</div><nav class="refund-pagination-pages" aria-label="Refund pagination"><button v-for="(l,i) in state.pagination.links" :key="i" class="refund-pager-btn" :class="{active:l.active,disabled:!l.url}" :disabled="!l.url" @click="page(l)" v-html="l.label.replace('&laquo;','‹').replace('&raquo;','›')"></button></nav></div></section></template>
<template v-else-if="mode==='create'||mode==='edit'"><section class="refund-hero"><div class="refund-hero-content"><span class="refund-hero-badge"><i class="bi bi-pencil-square"></i> Refund Management</span><h1>{{ mode==='edit'?'Edit Refund':'New Refund' }}</h1><p>{{ mode==='edit'?'Update the information associated with this refund.':'Select the order and provide the refund information.' }}</p></div><div class="refund-hero-actions"><a :href="indexUrl" class="refund-back-btn"><i class="bi bi-arrow-left"></i><span>Back to Refunds</span></a></div></section><div v-if="Object.keys(issues).length" class="refund-alert refund-alert-danger"><i class="bi bi-exclamation-triangle"></i><ul><li v-for="(msgs,key) in issues" :key="key">{{ msgs[0] }}</li></ul></div><form :action="mode==='edit'?updateUrl:storeUrl" method="POST" class="refund-form"><input type="hidden" name="_token" :value="csrf"><input v-if="mode==='edit'" type="hidden" name="_method" value="PUT"><div v-if="mode==='create'" class="refund-form-section"><div class="refund-section-heading"><div class="refund-section-icon"><i class="bi bi-bag-check"></i></div><div><h6>Order Information</h6><p>Select the order that requires a refund.</p></div></div><div class="refund-form-grid"><div class="refund-field-full"><label for="order_id" class="refund-form-label">Order <span class="required">*</span></label><select id="order_id" v-model="form.order_id" name="order_id" class="refund-form-control" required><option value="">Select an order</option><option v-for="o in supplied.orders||[]" :key="o.id" :value="o.id">#{{ o.order_number }} — {{ o.customer }} — ${{ Number(o.amount).toFixed(2) }}</option></select><div v-if="issues.order_id" class="refund-field-error">{{ issues.order_id[0] }}</div></div></div></div><div class="refund-form-section"><div class="refund-section-heading"><div class="refund-section-icon"><i class="bi bi-cash-stack"></i></div><div><h6>Refund Information</h6><p>Enter the amount and reason for the refund.</p></div></div><div class="refund-form-grid"><div><label for="amount" class="refund-form-label">Refund Amount <span class="required">*</span></label><input id="amount" v-model="form.amount" type="number" name="amount" class="refund-form-control" min="0.01" step="0.01" placeholder="0.00" required><div v-if="issues.amount" class="refund-field-error">{{ issues.amount[0] }}</div><span class="refund-field-help">The amount cannot exceed the refundable order amount.</span></div><div><label for="reason" class="refund-form-label">Refund Reason <span class="required">*</span></label><input id="reason" v-model="form.reason" name="reason" class="refund-form-control" maxlength="255" placeholder="Enter refund reason" required><div v-if="issues.reason" class="refund-field-error">{{ issues.reason[0] }}</div></div><div class="refund-field-full"><label for="note" class="refund-form-label">Internal Note</label><textarea id="note" v-model="form.note" name="note" rows="5" maxlength="2000" class="refund-form-control" placeholder="Add any additional information about this refund..."></textarea><span class="refund-field-help">This note is for administrative records.</span><div v-if="issues.note" class="refund-field-error">{{ issues.note[0] }}</div></div></div></div><div v-if="mode==='create'" class="refund-info"><div class="refund-info-icon"><i class="bi bi-info-circle"></i></div><div><strong>Refund Workflow</strong><p>New refunds are created with <strong>Pending</strong> status. After creation, you can review and approve, reject, or process the refund from the refund management page.</p></div></div><div class="refund-form-footer"><a :href="indexUrl" class="refund-cancel-btn"><i class="bi bi-x-lg"></i> Cancel</a><button type="submit" class="refund-submit-btn"><i class="bi bi-check-circle"></i> {{ mode==='edit'?'Update Refund':'Create Refund' }}</button></div></form></template>
<template v-else-if="mode==='show'"><section class="refund-hero"><div class="refund-hero-content"><span class="refund-hero-badge"><i class="bi bi-receipt"></i> Payments Recovery</span><h1>Refund Details</h1><p>Review refund information, order details and processing status.</p></div><div class="refund-hero-actions"><a :href="indexUrl" class="refund-back-btn"><i class="bi bi-arrow-left"></i><span>Back to Refunds</span></a><a v-if="supplied.edit_url" :href="supplied.edit_url" class="refund-add-btn"><i class="bi bi-pencil"></i><span>Edit Refund</span></a></div></section><div class="refund-summary"><div class="refund-summary-item"><span>Refund Number</span><strong>{{ refund.refund_number }}</strong></div><div class="refund-summary-item"><span>Refund Amount</span><strong class="refund-detail-amount">${{ Number(refund.amount).toFixed(2) }}</strong></div><div class="refund-summary-item"><span>Status</span><span class="refund-status" :class="`status-${refund.status}`"><i class="bi bi-circle-fill"></i>{{ refund.status }}</span></div><div class="refund-summary-item"><span>Requested</span><strong>{{ refund.requested_at||'—' }}</strong></div></div><div class="refund-show-grid"><div class="refund-show-main"><div class="refund-show-card"><div class="refund-show-header"><div><span class="eyebrow">REQUEST</span><h5>Refund Information</h5></div></div><div class="refund-show-body"><div class="refund-details"><div class="refund-detail"><span class="refund-detail-label">Order</span><strong>#{{ supplied.order?.order_number||'—' }}</strong></div><div class="refund-detail"><span class="refund-detail-label">Customer</span><strong>{{ supplied.customer?.name||'—' }} <small>{{ supplied.customer?.email }}</small></strong></div><div class="refund-detail"><span class="refund-detail-label">Reason</span><strong>{{ refund.reason }}</strong></div><div class="refund-detail"><span class="refund-detail-label">Internal Note</span><strong>{{ refund.note||'—' }}</strong></div><div class="refund-detail"><span class="refund-detail-label">Payment Status</span><strong>{{ supplied.payment?.payment_status||'—' }}</strong></div><div class="refund-detail"><span class="refund-detail-label">Processed By</span><strong>{{ supplied.processor||'—' }}</strong></div></div></div></div></div><aside class="refund-show-sidebar"><div class="refund-show-card"><div class="refund-show-header"><div><span class="eyebrow">ACTIONS</span><h5>Manage Refund</h5></div></div><div class="refund-show-body"><button v-if="refund.status==='pending'" class="refund-submit-btn w-100 mb-2" @click="action(supplied.status_url,'approved')">Approve refund</button><button v-if="refund.status==='pending'" class="refund-cancel-btn w-100 mb-2" @click="action(supplied.status_url,'rejected')">Reject refund</button><button v-if="refund.status==='approved'" class="refund-submit-btn w-100 mb-2" @click="action(supplied.status_url,'processed')">Process refund</button><button v-if="['pending','approved'].includes(refund.status)" class="refund-cancel-btn w-100" @click="action(supplied.status_url,'cancelled')">Cancel refund</button><div v-if="['processed','rejected','cancelled'].includes(refund.status)" class="refund-status-message">This refund is {{ refund.status }}.</div></div></div></aside></div></template>
</template>
